// Cloudflare binding surface for this Worker.
//
// `worker-configuration.d.ts` (generated by `wrangler types`, see the `types:cf`
// script) declares the workerd runtime globals -- including `D1Database`,
// `Fetcher` and the `cloudflare:workers` module -- and leaves `Cloudflare.Env`
// empty so projects can fill it in by declaration merging.
//
// Bindings are configured inline in `vite.config.ts` (`localBindingConfig`)
// rather than in a wrangler config file, so they are declared by hand here.
// Keep this in sync with `localBindingConfig` in vite.config.ts.
declare namespace Cloudflare {
  interface Env {
    /** Static asset fetcher injected by @cloudflare/vite-plugin. */
    ASSETS: Fetcher;
    /** D1 binding name — `D1_BINDING` in vite.config.ts. */
    DB: D1Database;
  }
}
